<?php use SwimlogStandalone\PersonalBests as PB;use SwimLogEvaluation\Workout;use SwimLogEvaluation\Evaluator; ?>
<section class="calendar-panel" aria-labelledby="personal-bests-title"><h2 id="personal-bests-title">Personal Bests</h2>
<?php if(is_wp_error($bests)): ?><p role="alert"><?php echo esc_html($bests->get_error_message()); ?></p>
<?php else:$b=$bests; ?>
<p>Your private swimming records. Running and walking are excluded. Drill and equipment eligibility follows the Swim Log evaluator.</p>
<form method="get" class="log-filters"><input type="hidden" name="screen" value="bests">
<label>Course <select name="course"><?php foreach(array('m'=>'Meters','yd'=>'Yards')as$key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected($b['course'],$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label>
<label>Record period <select name="period"><?php foreach(array('lifetime'=>'Lifetime','current'=>'Current age group','historical'=>'Historical age group')as$key=>$label):if(($key==='current'&&!$b['current'])||($key==='historical'&&!$b['historical']))continue; ?><option value="<?php echo esc_attr($key); ?>" <?php selected($b['period'],$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label>
<?php if($b['historical']): ?><label>Historical age group <select name="age_group"><?php foreach($b['historical']as$label): ?><option <?php selected($b['selected'],$label); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><?php endif; ?><button>View records</button></form>
<p><?php echo esc_html($b['period']==='lifetime'?'Lifetime':('Age group '.($b['period']==='current'?$b['current']:$b['selected']))); ?> · <?php echo esc_html($b['course']==='m'?'Meters':'Yards'); ?></p>
<?php if(!$b['pbs']): ?><p>No personal bests are available for this record period and course.</p><?php else: ?>
<div class="detail-table-wrap" role="region" aria-label="Swimming personal bests" tabindex="0"><table><thead><tr><th scope="col">Distance</th><?php foreach($b['strokes']as$label): ?><th scope="col"><?php echo esc_html($label); ?></th><?php endforeach; ?></tr></thead><tbody>
<?php foreach(Evaluator::DISTANCES as$d):if(empty($b['pbs'][$d]))continue; ?><tr><th scope="row"><?php echo esc_html($d.' '.$b['course']); ?></th><?php foreach($b['strokes']as$code=>$label):$p=$b['pbs'][$d][$code]??null; ?><td><?php if($p): ?><a data-workout-id="<?php echo esc_attr((int)$p->workout_id); ?>" aria-haspopup="dialog" aria-expanded="false" href="<?php echo esc_url(PB::url($b,array('workout'=>(int)$p->workout_id))); ?>"><?php echo esc_html(Workout::format_duration($p->duration_ms)); ?></a><?php if($b['period']!=='lifetime'&&isset($b['lifetime'][$d][$code])&&(int)$b['lifetime'][$d][$code]->id===(int)$p->id): ?> <span aria-label="Lifetime Personal Best">★</span><?php endif; ?><br><small><?php echo esc_html(substr($p->achieved_at,0,10)); ?></small><?php else: ?>—<?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<h3>PB Progression</h3><p>Lifetime improvements for the selected swimming distance and stroke.</p>
<form method="get" class="log-filters"><input type="hidden" name="screen" value="bests"><?php foreach(array('course','period')as$key): ?><input type="hidden" name="<?php echo esc_attr($key); ?>" value="<?php echo esc_attr($b[$key]); ?>"><?php endforeach; ?><input type="hidden" name="age_group" value="<?php echo esc_attr($b['selected']); ?>">
<label>Distance <select name="history_distance"><option value="0">Choose distance</option><?php foreach(Evaluator::DISTANCES as$d): ?><option value="<?php echo esc_attr($d); ?>" <?php selected($b['distance'],(string)$d); ?>><?php echo esc_html($d.' '.$b['course']); ?></option><?php endforeach; ?></select></label>
<label>Stroke <select name="history_stroke"><option value="">Choose stroke</option><?php foreach($b['strokes']as$code=>$label):if($code==='OVERALL')continue; ?><option value="<?php echo esc_attr($code); ?>" <?php selected($b['stroke'],$code); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><button>Show progression</button></form>
<?php if($b['distance']!=='0'&&$b['stroke']!==''):if($b['progressionUnavailable']): ?><p role="status">Progression history is unavailable in the installed plugin. Your personal bests remain available.</p><?php elseif(!$b['progression']): ?><p>No progression records found for that distance and stroke.</p><?php else: ?><div class="detail-table-wrap" role="region" aria-label="Personal best progression" tabindex="0"><table><thead><tr><th>Date</th><th>Time</th><th>Workout</th></tr></thead><tbody><?php foreach($b['progression']as$p): ?><tr><td><?php echo esc_html(substr($p->achieved_at,0,10)); ?></td><td><?php echo esc_html(Workout::format_duration($p->duration_ms)); ?></td><td><a data-workout-id="<?php echo esc_attr((int)$p->workout_id); ?>" aria-haspopup="dialog" aria-expanded="false" href="<?php echo esc_url(PB::url($b,array('workout'=>(int)$p->workout_id))); ?>">View workout</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif;endif;endif; ?></section>
